//! Tests for mirror metadata integrity verification + fixture generation.
//!
//! Fixtures under `tests/fixtures/` are SYNTHETIC, signed with throwaway
//! test keys generated by `generate_fixtures` — they are not trust anchors
//! for any real distro. Regenerate with:
//!
//! ```text
//! cargo test -p monopsony-mirror generate_fixtures -- --ignored
//! ```
//!
//! The in-memory round-trip tests do not read fixtures; the fixture-based
//! tests prove the checked-in bytes still verify (format provenance).

use std::io::{Cursor, Write};
use std::path::PathBuf;

use flate2::write::GzEncoder;
use flate2::Compression;
use rsa::pkcs8::EncodePublicKey;

use super::*;

fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

/// A small synthetic Release document in the real Debian field/block layout.
const RELEASE_TEXT: &str = "\
Origin: monopsony-test
Label: monopsony-test
Suite: stable
Codename: trixie
Date: Sat, 31 Oct 2026 00:00:00 UTC
SHA256:
 1111111111111111111111111111111111111111111111111111111111111111 1234 main/binary-amd64/Packages.gz
 2222222222222222222222222222222222222222222222222222222222222222 100 main/binary-amd64/Packages.xz
";

/// Synthetic APKINDEX text in the real apk-tools field layout.
const APKINDEX_TEXT: &str = "\
C:Q1/dy61M3wkuQsY22lN0Ou8WqzFTQ=
P:7zip
V:24.09-r0
A:x86_64
S:915773

C:Q1aGVsbG8gd29ybGQgZml4dHVyZSEhIQ==
P:busybox
V:1.37.0-r0
A:x86_64
S:486302
";

struct TestPgpKey {
    secret: pgp::composed::SignedSecretKey,
    public_armored: String,
}

fn generate_pgp_test_key() -> TestPgpKey {
    use pgp::composed::{KeyType, SecretKeyParamsBuilder};

    let params = SecretKeyParamsBuilder::default()
        .key_type(KeyType::Ed25519Legacy)
        .can_certify(true)
        .can_sign(true)
        .primary_user_id("Monopsony Fixture Key <fixture@invalid>".into())
        .build()
        .expect("key params");
    let secret = params.generate(rand::thread_rng()).expect("keygen");
    let public_armored = SignedPublicKey::from(secret.clone())
        .to_armored_string(Default::default())
        .expect("armor public key");
    TestPgpKey {
        secret,
        public_armored,
    }
}

/// Build a tar archive from (name, payload) pairs, as apk-tools does.
fn build_tar(entries: &[(&str, Vec<u8>)]) -> Vec<u8> {
    let mut builder = tar::Builder::new(Vec::new());
    for (name, data) in entries {
        let mut header = tar::Header::new_gnu();
        header.set_size(data.len() as u64);
        header.set_mode(0o644);
        header.set_cksum();
        builder
            .append_data(&mut header, name, Cursor::new(data.clone()))
            .expect("tar append");
    }
    builder.into_inner().expect("tar finish")
}

fn gzip_bytes(data: &[u8]) -> Vec<u8> {
    let mut encoder = GzEncoder::new(Vec::new(), Compression::default());
    encoder.write_all(data).expect("gzip write");
    encoder.finish().expect("gzip finish")
}

/// Build a two-member APKINDEX.tar.gz the way apk-tools does, and the
/// matching SPKI PEM public key. Returns (bundle, pubkey_pem).
/// `tamper_member2` flips one byte inside member 2's compressed stream
/// AFTER signing — the negative control for the whole pipeline.
fn build_apkindex_bundle(tamper_member2: bool) -> (Vec<u8>, String, Vec<u8>, RsaPublicKey) {
    let member2_tar = build_tar(&[
        ("DESCRIPTION", b"monopsony test index\n".to_vec()),
        ("APKINDEX", APKINDEX_TEXT.as_bytes().to_vec()),
    ]);
    let member2_raw = gzip_bytes(&member2_tar);
    let (public, sig) = sign_apkindex_for_test(&member2_raw, 2048).expect("rsa sign");
    let sign_entry_name = ".SIGN.RSA.mirrors-test-key.rsa.pub".to_string();
    let member1_tar = build_tar(&[(sign_entry_name.as_str(), sig)]);
    let member1_raw = gzip_bytes(&member1_tar);

    let mut member2_out = member2_raw.clone();
    if tamper_member2 {
        let at = member2_out.len() / 2;
        member2_out[at] ^= 0x01;
    }
    let mut bundle = member1_raw;
    bundle.extend_from_slice(&member2_out);
    let pem = public
        .to_public_key_pem(rsa::pkcs8::LineEnding::LF)
        .expect("spki pem");
    (bundle, pem, member2_raw, public)
}

#[test]
fn hash_policy_parse() {
    assert_eq!(HashPolicy::parse("fail-closed"), HashPolicy::FailClosed);
    assert_eq!(HashPolicy::parse("fail-open"), HashPolicy::FailOpen);
    // Unknown values fail closed, never silently disable enforcement.
    assert_eq!(HashPolicy::parse(""), HashPolicy::FailClosed);
    assert_eq!(HashPolicy::parse("typo"), HashPolicy::FailClosed);
    assert_eq!(HashPolicy::parse(" fail-open "), HashPolicy::FailOpen);
}

#[test]
fn parse_sign_member_types() {
    let (t, kf) =
        parse_sign_member(".SIGN.RSA.alpine-devel@lists-6165ee59.rsa.pub").expect("RSA member");
    assert_eq!(t, ApkSigType::RsaSha1);
    assert_eq!(kf, "alpine-devel@lists-6165ee59.rsa.pub");
    let (t, _) = parse_sign_member(".SIGN.RSA512.somekey.pub").expect("RSA512 member");
    assert_eq!(t, ApkSigType::RsaSha512);
    let (t, _) = parse_sign_member(".SIGN.RSA256.somekey.pub").expect("RSA256 member");
    assert_eq!(t, ApkSigType::RsaSha256);
    let (t, _) = parse_sign_member(".SIGN.DSA.somekey.pub").expect("DSA member");
    assert_eq!(t, ApkSigType::Dsa);
    assert!(parse_sign_member("APKINDEX").is_none());
    assert!(parse_sign_member(".SIGN.WEIRD.x").is_none());
}

#[test]
fn release_sha256_extracts_declared_hashes() {
    // Verified-release text comes back CRLF-normalized from the cleartext
    // framework — prove the \r handling while parsing.
    let crlf = RELEASE_TEXT.replace('\n', "\r\n");
    assert_eq!(
        release_sha256_for(&crlf, "main/binary-amd64/Packages.gz"),
        Some("1".repeat(64))
    );
    assert_eq!(
        release_sha256_for(&crlf, "main/binary-amd64/Packages.xz"),
        Some("2".repeat(64))
    );
    assert_eq!(release_sha256_for(&crlf, "main/binary-amd64/missing"), None);
    // A SHA512 block must not satisfy SHA256 lookups.
    let wrong_block = "SHA512:\n abc 10 main/binary-amd64/Packages.gz\n";
    assert_eq!(
        release_sha256_for(wrong_block, "main/binary-amd64/Packages.gz"),
        None
    );
}

#[test]
fn alpine_roundtrip_and_tamper() {
    let (bundle, pem, _member2_raw, _public) = build_apkindex_bundle(false);
    let keys = load_trusted_keys(&[pem]).expect("load key");
    let verified = verify_apkindex_tar_gz(&bundle, &keys).expect("verify");
    assert!(verified.apkindex_text.contains("P:7zip"));
    assert!(verified.apkindex_text.contains("P:busybox"));

    // Tampered compressed payload must fail.
    let (bad_bundle, pem2, _, _) = build_apkindex_bundle(true);
    let keys2 = load_trusted_keys(&[pem2]).expect("load key");
    match verify_apkindex_tar_gz(&bad_bundle, &keys2) {
        Err(IntegrityError::SignatureMismatch) => {}
        other => panic!("expected SignatureMismatch, got {:?}", other.map(|_| ())),
    }

    // Unpinned mirror fails with NoTrustedKeys, never a silent pass.
    let empty = TrustedKeys::default();
    match verify_apkindex_tar_gz(&bundle, &empty) {
        Err(IntegrityError::NoTrustedKeys) => {}
        other => panic!("expected NoTrustedKeys, got {:?}", other.map(|_| ())),
    }
}

#[test]
fn alpine_rejects_foreign_key() {
    // Bundle signed by key A; verification attempted with key B (a separate
    // keygen call) must fail closed.
    let (bundle, _pem_a, _m2, _public_a) = build_apkindex_bundle(false);
    let (_, pem_b, _, _) = build_apkindex_bundle(false);
    let keys = load_trusted_keys(&[pem_b]).expect("load key");
    match verify_apkindex_tar_gz(&bundle, &keys) {
        Err(IntegrityError::SignatureMismatch) => {}
        Ok(_) => panic!("foreign key must not verify"),
        other => panic!("expected SignatureMismatch, got {:?}", other.map(|_| ())),
    }
}

#[test]
fn load_trusted_keys_detects_formats() {
    let (_, pem, _, _) = build_apkindex_bundle(false);
    let keys = load_trusted_keys(&[pem]).expect("spki inline");
    assert_eq!(keys.rsa_spki.len(), 1);
    assert!(keys.openpgp.is_empty());

    let result = load_trusted_keys(&["not a key at all".to_string()]);
    assert!(result.is_err(), "unrecognized format must error");
}

#[test]
fn debian_clearsign_and_detached_roundtrip() {
    let key = generate_pgp_test_key();
    let keys = load_trusted_keys(std::slice::from_ref(&key.public_armored)).expect("load pgp key");
    assert_eq!(keys.openpgp.len(), 1);

    // Clearsigned InRelease.
    use pgp::types::Password;
    let clearsigned = CleartextSignedMessage::sign(
        rand::thread_rng(),
        RELEASE_TEXT,
        &*key.secret,
        &Password::empty(),
    )
    .expect("clearsign");
    let armor = clearsigned
        .to_armored_string(Default::default())
        .expect("armor");
    let verified = verify_clearsigned_release(armor.as_bytes(), &keys).expect("verify InRelease");
    assert!(verified.release_text.contains("Suite: stable"));
    assert!(
        verified
            .release_text
            .contains("main/binary-amd64/Packages.gz"),
        "checksum anchor must come from the signed text"
    );

    // Tampered cleartext must fail.
    let tampered = armor.replace("Suite: stable", "Suite: unstable");
    assert_ne!(tampered, armor);
    match verify_clearsigned_release(tampered.as_bytes(), &keys) {
        Err(IntegrityError::SignatureMismatch) => {}
        other => panic!("expected SignatureMismatch, got {:?}", other.map(|_| ())),
    }

    // Detached Release.gpg over the exact Release bytes.
    use pgp::composed::DetachedSignature as DetachedSigType;
    use pgp::crypto::hash::HashAlgorithm;
    let detached = DetachedSigType::sign_binary_data(
        rand::thread_rng(),
        &*key.secret,
        &Password::empty(),
        HashAlgorithm::Sha256,
        Cursor::new(RELEASE_TEXT.as_bytes()),
    )
    .expect("detached sign");
    let sig_armored = detached
        .to_armored_string(Default::default())
        .expect("armor sig");
    verify_detached_release(RELEASE_TEXT.as_bytes(), sig_armored.as_bytes(), &keys)
        .expect("verify detached");

    // Byte-flip in the Release body must fail the detached check.
    let mut flipped = RELEASE_TEXT.as_bytes().to_vec();
    let at = flipped.len() / 2;
    flipped[at] ^= 0x01;
    match verify_detached_release(&flipped, sig_armored.as_bytes(), &keys) {
        Err(IntegrityError::SignatureMismatch) => {}
        other => panic!("expected SignatureMismatch, got {:?}", other.map(|_| ())),
    }
}

#[test]
fn alpine_sha256_signature_type_roundtrip() {
    // RSA512/RSA256 member names select their digests; sign+verify with the
    // SHA512 variant to prove the mapping is not hardwired to SHA1.
    let member2_tar = build_tar(&[("APKINDEX", APKINDEX_TEXT.as_bytes().to_vec())]);
    let member2_raw = gzip_bytes(&member2_tar);

    use rsa::pkcs1v15::SigningKey;
    use rsa::signature::{RandomizedSigner, SignatureEncoding};
    let mut rng = rand::thread_rng();
    let private = RsaPrivateKey::new(&mut rng, 2048).expect("keygen");
    let public = RsaPublicKey::from(&private);
    let signing = SigningKey::<Sha512>::new(private);
    let sig = signing.sign_with_rng(&mut rng, &member2_raw);

    let member1_tar = build_tar(&[(".SIGN.RSA512.mirrors-test-key.rsa.pub", sig.to_vec())]);
    let mut bundle = gzip_bytes(&member1_tar);
    bundle.extend_from_slice(&member2_raw);

    let pem = public
        .to_public_key_pem(rsa::pkcs8::LineEnding::LF)
        .expect("pem");
    let keys = load_trusted_keys(&[pem]).expect("load key");
    let verified = verify_apkindex_tar_gz(&bundle, &keys).expect("verify RSA512");
    assert!(verified.apkindex_text.contains("P:7zip"));
}

/// Generate/refresh the checked-in fixtures. Run explicitly:
/// `cargo test -p monopsony-mirror generate_fixtures -- --ignored`
#[test]
#[ignore]
fn generate_fixtures() {
    let dir = fixtures_dir();
    std::fs::create_dir_all(dir.join("debian")).expect("mkdir debian");
    std::fs::create_dir_all(dir.join("alpine")).expect("mkdir alpine");

    // Debian fixtures.
    let key = generate_pgp_test_key();
    std::fs::write(dir.join("debian/Release"), RELEASE_TEXT).expect("write Release");
    use pgp::composed::DetachedSignature as DetachedSigType;
    use pgp::crypto::hash::HashAlgorithm;
    use pgp::types::Password;
    let clearsigned = CleartextSignedMessage::sign(
        rand::thread_rng(),
        RELEASE_TEXT,
        &*key.secret,
        &Password::empty(),
    )
    .expect("clearsign");
    let armor = clearsigned
        .to_armored_string(Default::default())
        .expect("armor");
    // Tampered variant: same signature armor, modified cleartext.
    let tampered = armor.replace("Suite: stable", "Suite: unstable");
    std::fs::write(dir.join("debian/InRelease"), &armor).expect("write InRelease");
    std::fs::write(dir.join("debian/InRelease.bad"), tampered).expect("write InRelease.bad");
    let detached = DetachedSigType::sign_binary_data(
        rand::thread_rng(),
        &*key.secret,
        &Password::empty(),
        HashAlgorithm::Sha256,
        Cursor::new(RELEASE_TEXT.as_bytes()),
    )
    .expect("detached sign");
    std::fs::write(
        dir.join("debian/Release.gpg"),
        detached
            .to_armored_string(Default::default())
            .expect("armor"),
    )
    .expect("write Release.gpg");
    std::fs::write(dir.join("debian/release-key.pub.asc"), &key.public_armored).expect("write key");

    // Alpine fixtures.
    let (bundle, pem, _m2, _public) = build_apkindex_bundle(false);
    std::fs::write(dir.join("alpine/APKINDEX.tar.gz"), &bundle).expect("write APKINDEX.tar.gz");
    std::fs::write(dir.join("alpine/alpine-test-key.pub"), &pem).expect("write key");
    let (bad_bundle, _, _, _) = build_apkindex_bundle(true);
    std::fs::write(dir.join("alpine/APKINDEX.tampered.tar.gz"), &bad_bundle)
        .expect("write tampered");

    std::fs::write(
        dir.join("README.md"),
        format!(
            "SYNTHETIC fixtures — signed with throwaway test keys, NOT real \
             distro trust anchors.\n\nRegenerate:\n  cargo test -p monopsony-mirror \
             generate_fixtures -- --ignored\n\n\
             debian/: clearsigned InRelease + detached Release.gpg over Release \
             (apt-secure(8) layout).\nalpine/: two-member APKINDEX.tar.gz \
             (.SIGN.RSA.<key>.rsa.pub over member 2 compressed bytes, \
             RSA-PKCS1v1.5-SHA1 — the live Alpine scheme).\nGenerated {}.\n",
            chrono::Utc::now().to_rfc3339()
        ),
    )
    .expect("write README");
}

#[test]
fn fixtures_still_verify() {
    let dir = fixtures_dir();
    let debian = dir.join("debian");
    let alpine = dir.join("alpine");
    if !debian.exists() || !alpine.exists() {
        panic!(
            "fixtures missing — run: cargo test -p monopsony-mirror generate_fixtures -- --ignored"
        );
    }

    // Debian: valid InRelease verifies against the pinned fixture key.
    let key_text = std::fs::read_to_string(debian.join("release-key.pub.asc")).expect("key");
    let keys = load_trusted_keys(&[key_text]).expect("load key");
    let inrelease = std::fs::read(debian.join("InRelease")).expect("InRelease");
    let verified = verify_clearsigned_release(&inrelease, &keys).expect("verify");
    assert!(verified.release_text.contains("SHA256:"));
    // Tampered variant must fail.
    let bad = std::fs::read(debian.join("InRelease.bad")).expect("InRelease.bad");
    match verify_clearsigned_release(&bad, &keys) {
        Err(IntegrityError::SignatureMismatch) => {}
        other => panic!("expected SignatureMismatch, got {:?}", other.map(|_| ())),
    }
    // Detached pair.
    let release = std::fs::read(debian.join("Release")).expect("Release");
    let sig = std::fs::read(debian.join("Release.gpg")).expect("Release.gpg");
    verify_detached_release(&release, &sig, &keys).expect("detached verify");

    // Alpine: valid bundle verifies; tampered bundle fails.
    let key_text = std::fs::read_to_string(alpine.join("alpine-test-key.pub")).expect("key");
    let keys = load_trusted_keys(&[key_text]).expect("load key");
    let bundle = std::fs::read(alpine.join("APKINDEX.tar.gz")).expect("APKINDEX.tar.gz");
    let verified = verify_apkindex_tar_gz(&bundle, &keys).expect("verify");
    assert!(verified.apkindex_text.contains("P:7zip"));
    let bad = std::fs::read(alpine.join("APKINDEX.tampered.tar.gz")).expect("tampered");
    match verify_apkindex_tar_gz(&bad, &keys) {
        Err(IntegrityError::SignatureMismatch) => {}
        other => panic!("expected SignatureMismatch, got {:?}", other.map(|_| ())),
    }
}
